SER_META = {
    "d905": {"g": "库存", "sg": "铜库存", "n": "LME铜库存", "u": "吨"},
    "d906": {"g": "库存", "sg": "铜库存", "n": "SHFE铜库存（期货库存周报）", "u": "吨"},
    "d907": {"g": "库存", "sg": "铜库存", "n": "SHFE铜库存（日度·仓单日报）", "u": "吨"},
}

WM_URL = "https://www.westmetall.com/en/markdaten.php?action=table&field=LME_Cu_cash"
MONTHS = {"January": 1, "February": 2, "March": 3, "April": 4, "May": 5, "June": 6,
          "July": 7, "August": 8, "September": 9, "October": 10, "November": 11, "December": 12}


def fetch_lme_cu():
    """westmetall LME 铜库存（表第4列）。任何异常都返回空列表。"""
    try:
        req = urllib.request.Request(WM_URL, headers={"User-Agent": "Mozilla/5.0"})
        html = urllib.request.urlopen(req, timeout=30).read().decode("utf-8", "replace")
        out = []
        for row in re.findall(r"<tr[^>]*>(.*?)</tr>", html, re.S):
            cells = [re.sub(r"<[^>]+>", "", c).strip() for c in re.findall(r"<td[^>]*>(.*?)</td>", row, re.S)]
            if len(cells) < 4:
                continue
            m = re.match(r"(\d{1,2})\. ([A-Za-z]+) (\d{4})", cells[0])
            if not m or m.group(2) not in MONTHS:
                continue
            v = cells[3].replace(",", "")
            if not v.replace(".", "").isdigit():
                continue
            d = f"{m.group(3)}-{MONTHS[m.group(2)]:02d}-{int(m.group(1)):02d}"
            out.append([d, float(v)])
        return sorted(out)
    except Exception as e:
        print(f"  westmetall 抓取失败（用快照兜底）: {e}")
        return []


def merge(pts, new):
    m = {d: v for d, v in pts}
    for d, v in new:
        if d not in m and v > 0:
            m[d] = v
    return [[d, m[d]] for d in sorted(m)]


def main():
    db_path = ROOT / "db_data.js"
    raw = db_path.read_text(encoding="utf-8")
    i0 = raw.index("[")
    data, _ = json.JSONDecoder().raw_decode(raw, i0)
    head, tail = raw[:i0], raw[raw.rindex("]") + 1:]

    live = fetch_lme_cu()
    new_series = []
    for k, pts in SNAPSHOT.items():
        pts = [list(p) for p in pts]
        if k == "d905" and live:
            lastv = pts[-1][1] if pts else 0
            fresh = [p for p in live if p[0] > pts[-1][0]] if pts else live
            if fresh and lastv and abs(fresh[0][1] / lastv - 1) > 0.6:
                print(f"  {k}: westmetall 首点跳变超 60%，忽略本次抓取")
                fresh = []
            pts = merge(pts, fresh)
            if fresh:
                print(f"  {k}: 快照 {len(SNAPSHOT[k])} 点 + westmetall 新增 {len(fresh)} 点，最新 {pts[-1][0]} = {pts[-1][1]}")
            else:
                print(f"  {k}: 快照 {len(pts)} 点（无新增）")
        else:
            print(f"  {k}: 快照 {len(pts)} 点")
        meta = SER_META[k]
        new_series.append({"g": meta["g"], "sg": meta["sg"], "k": k, "n": meta["n"], "u": meta["u"], "s": pts})

    data = [x for x in data if x.get("k") not in SNAPSHOT] + new_series
    new_main = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    db_path.write_text(f"{head}{new_main}{tail}", encoding="utf-8")

    check = db_path.read_text(encoding="utf-8")
    json.loads(check[check.index("["):check.rindex("]") + 1])
    for k in SNAPSHOT:
        if f'"k":"{k}"' not in check:
            raise SystemExit(f"自检失败：{k} 未写入")
    print(f"OK：铜库存序列 d905/d906/d907 已补回，主数组序列数 {len(data)}")


if __name__ == "__main__":
    sys.exit(main())
